#!/usr/bin/env python3
# Minimal UCI engine that always claims Black is completely winning.
import sys

def send(msg):
    sys.stdout.write(msg + "\n")
    sys.stdout.flush()

while True:
    line = sys.stdin.readline()
    if not line:
        break
    cmd = line.strip()
    if cmd == "uci":
        send("id name DummyEngine")
        send("id author OpenAI")
        send("uciok")
    elif cmd == "isready":
        send("readyok")
    elif cmd.startswith("setoption"):
        # ignore any options
        continue
    elif cmd in ("ucinewgame", "ponderhit"):
        continue
    elif cmd.startswith("position"):
        # we do not need to store the position because our evaluation is constant
        continue
    elif cmd.startswith("go"):
        # Report an extremely negative evaluation for White and return null move
        send("info score cp -9999")
        send("bestmove 0000")
    elif cmd == "quit":
        break
PY"}
